// frontend/src/components/AutomationMetrics/AutomationCreationTab.js
import React, { useEffect, useMemo, useState } from "react";
import "../../styles/roiTabs.css";
import "../../styles/RecordEntry.css";

// Shared dropdown values (Section 2)
const FY_OPTIONS = [
  "All Years",
  "FY-2019",
  "FY-2020",
  "FY-2021",
  "FY-2022",
  "FY-2023",
  "FY-2024",
  "FY-2025",
  "FY-2026 (To-Date)",
];

const BREAKDOWN_OPTIONS = [
  "Breakdown by App Fmk & Portfolio",
  "Breakdown by Applications",
];

function SimpleTable({ headers, rows }) {
  if (!headers?.length && !rows?.length) return null;
  return (
    <div className="table-wrap" style={{ overflowX: "auto" }}>
      <table className="roi-table">
        <thead>
          <tr>
            {(headers || []).map((h, i) => (
              <th key={i}>{h || ""}</th>
            ))}
          </tr>
        </thead>
        <tbody>
          {(rows || []).map((r, ri) => (
            <tr key={ri}>
              {(headers || []).map((_, ci) => (
                <td key={ci}>
                  {/* Placeholder: each cell will later fetch its own value */}
                  {r?.[ci] ?? ""}
                </td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

export default function AutomationCreationTab() {
  // Section 1: consolidated
  const [consData, setConsData] = useState({ headers: [], rows: [] });
  const [consBusy, setConsBusy] = useState(false);
  const [consErr, setConsErr] = useState("");

  // Section 2: monthly breakdown
  const [fy, setFy] = useState("All Years");
  const [breakdown, setBreakdown] = useState(BREAKDOWN_OPTIONS[0]);
  const [monData, setMonData] = useState({ headers: [], rows: [] });
  const [monBusy, setMonBusy] = useState(false);
  const [monErr, setMonErr] = useState("");

  // Fetch Section 1 (sheet: Creation)
  useEffect(() => {
    const run = async () => {
      try {
        setConsBusy(true);
        setConsErr("");
        const res = await fetch(
          "http://localhost:5000/api/automationmetricsdatafetch?tab=creation&view=consolidated"
        );
        const j = await res.json();
        setConsData({
          headers: j?.headers || [],
          rows: j?.rows || [],
        });
      } catch (e) {
        setConsErr("Failed to load Consolidated View");
        console.error(e);
      } finally {
        setConsBusy(false);
      }
    };
    run();
  }, []);

  // Fetch Section 2 (sheet: MonthlyCreation)
  useEffect(() => {
    const run = async () => {
      try {
        setMonBusy(true);
        setMonErr("");
        const qs = new URLSearchParams({
          tab: "creation",
          view: "monthly",
          fy: fy || "",
          breakdown: breakdown || "",
        }).toString();
        const res = await fetch(
          "http://localhost:5000/api/automationmetricsdatafetch?" + qs
        );
        const j = await res.json();
        setMonData({
          headers: j?.headers || [],
          rows: j?.rows || [],
        });
      } catch (e) {
        setMonErr("Failed to load Monthly Breakdown");
        console.error(e);
      } finally {
        setMonBusy(false);
      }
    };
    run();
  }, [fy, breakdown]);

  return (
    <div className="tab-wrap">
      {/* Section 1 */}
      <div className="tab-section tab-section-yellow">Section 1: Consolidated View</div>
      {consBusy ? (
        <div className="text-gray-600" style={{ marginBottom: 12 }}>Loading…</div>
      ) : consErr ? (
        <div className="text-red-600" style={{ marginBottom: 12 }}>{consErr}</div>
      ) : (
        <SimpleTable headers={consData.headers} rows={consData.rows} />
      )}

      {/* Section 2 */}
      <div className="tab-section tab-section-yellow" style={{ marginTop: 24 }}>
        Section 2: Monthly Breakdown
      </div>

      <div className="grid-2" style={{ gap: 12, marginBottom: 12 }}>
        <div>
          <label className="small-label">Select a year</label>
          <select
            className="input"
            value={fy}
            onChange={(e) => setFy(e.target.value)}
          >
            {FY_OPTIONS.map((o) => (
              <option key={o} value={o}>{o}</option>
            ))}
          </select>
        </div>

        <div>
          <label className="small-label">Select a Breakdown View</label>
          <select
            className="input"
            value={breakdown}
            onChange={(e) => setBreakdown(e.target.value)}
          >
            {BREAKDOWN_OPTIONS.map((o) => (
              <option key={o} value={o}>{o}</option>
            ))}
          </select>
        </div>
      </div>

      {monBusy ? (
        <div className="text-gray-600">Loading…</div>
      ) : monErr ? (
        <div className="text-red-600">{monErr}</div>
      ) : (
        <SimpleTable headers={monData.headers} rows={monData.rows} />
      )}
    </div>
  );
}
